function swimFrameLayout(path, frame) {
    const extra = bluegroveLayouts[path];
    if (extra) {
        const [x, y] = extra.shifts[frame] ?? [0, 0];
        return { originX: .5 + x / extra.cell, originY: .5 + y / extra.cell, scale: 1 };
    }
    const [x, y, scale] = layouts[path]?.[frame] ?? [0, 0, 1];
    return { originX: .5 + x / 96, originY: .5 + y / 96, scale: 1 / scale };
}

